using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class DashboardPage:UserControl{public DashboardPage(){BackColor=Theme.Background;var wrap=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=true};wrap.Controls.Add(Card(L.Fa?"فرصت‌های باز":"Open jobs","SELECT COUNT(*) FROM Jobs WHERE Status='Open'"));wrap.Controls.Add(Card(L.Fa?"کارجویان":"Candidates","SELECT COUNT(*) FROM Candidates"));wrap.Controls.Add(Card(L.Fa?"درخواست‌ها":"Applications","SELECT COUNT(*) FROM Applications"));wrap.Controls.Add(Card(L.Fa?"شرکت‌های فعال":"Active companies","SELECT COUNT(*) FROM Companies WHERE IsActive=1"));Controls.Add(wrap);var panel=Ui.Card();panel.Dock=DockStyle.Bottom;panel.Height=280;var title=Ui.Label(L.Fa?"آخرین فرصت‌های شغلی":"Latest job opportunities",14,true);title.Dock=DockStyle.Top;var g=Ui.Grid();g.DataSource=Database.Query("SELECT TOP 8 j.Title AS [عنوان],c.Name AS [شرکت],j.City AS [شهر],j.Status AS [وضعیت],j.CreatedAt AS [تاریخ] FROM Jobs j LEFT JOIN Companies c ON c.Id=j.CompanyId ORDER BY j.Id DESC");panel.Controls.Add(g);panel.Controls.Add(title);Controls.Add(panel);}Panel Card(string title,string sql){var p=Ui.Card();p.Width=235;p.Height=125;var n=Ui.Label(Convert.ToString(Database.Scalar(sql)),26,true);n.ForeColor=Theme.Primary;n.Top=45;n.Left=18;var t=Ui.Label(title,10,true);t.Top=16;t.Left=18;p.Controls.Add(t);p.Controls.Add(n);return p;}}}